-- ============================================
-- LUMA — Thème 3 (Entretien) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"recruiter": "le recruteur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "recruiter", "text": "Thanks for coming in. Let''s start — could you tell me a bit about yourself?", "text_fr": "Merci d''être venu. Commençons — vous pourriez me parler un peu de vous ?", "choices": [{"text": "Of course. I''m a marketing specialist with five years of experience in digital campaigns.", "text_fr": "Bien sûr. Je suis spécialiste marketing avec cinq ans d''expérience en campagnes digitales.", "next": "n2"}, {"text": "Sure — I recently graduated and I''m eager to start my career in this field.", "text_fr": "Bien sûr — j''ai récemment obtenu mon diplôme et j''ai hâte de commencer ma carrière dans ce domaine.", "next": "n2b"}]}, "n2": {"speaker": "recruiter", "text": "Great, and what would you say is your biggest professional achievement?", "text_fr": "Super, et quel serait selon vous votre plus grande réussite professionnelle ?", "choices": [{"text": "I led a campaign that increased engagement by 40% in six months.", "text_fr": "J''ai dirigé une campagne qui a augmenté l''engagement de 40% en six mois.", "next": "n3"}, {"text": "I helped rebrand a small company that then doubled its customer base.", "text_fr": "J''ai aidé à repositionner une petite entreprise qui a ensuite doublé sa clientèle.", "next": "n3"}]}, "n2b": {"speaker": "recruiter", "text": "That''s great energy. What made you choose this field?", "text_fr": "C''est une belle énergie. Qu''est-ce qui vous a fait choisir ce domaine ?", "choices": [{"text": "I''ve always loved solving problems creatively, and this field combines both.", "text_fr": "J''ai toujours adoré résoudre des problèmes de façon créative, et ce domaine combine les deux.", "next": "n3"}, {"text": "I did an internship last year and completely fell in love with the work.", "text_fr": "J''ai fait un stage l''an dernier et je suis complètement tombé amoureux de ce travail.", "next": "n3"}]}, "n3": {"speaker": "recruiter", "text": "Impressive. And how would your previous colleagues describe you?", "text_fr": "Impressionnant. Et comment vos anciens collègues vous décriraient-ils ?", "choices": [{"text": "Reliable, detail-oriented, and always willing to help others.", "text_fr": "Fiable, minutieux, et toujours prêt à aider les autres.", "next": "n4"}, {"text": "Probably as someone who stays calm under pressure.", "text_fr": "Probablement comme quelqu''un qui reste calme sous pression.", "next": "n4"}]}, "n4": {"speaker": "recruiter", "text": "Good to know. What are you hoping to find in your next role?", "text_fr": "Bon à savoir. Qu''espérez-vous trouver dans votre prochain poste ?", "choices": [{"text": "A team where I can grow and take on more responsibility.", "text_fr": "Une équipe où je peux grandir et prendre plus de responsabilités.", "next": "n5"}, {"text": "A company with a strong mission I can genuinely believe in.", "text_fr": "Une entreprise avec une mission forte à laquelle je peux vraiment croire.", "next": "n5"}]}, "n5": {"speaker": "recruiter", "text": "That aligns well with what we offer here. Thanks for that introduction!", "text_fr": "Ça correspond bien à ce qu''on propose ici. Merci pour cette présentation !", "choices": [{"text": "Thank you, I''m excited to be here.", "text_fr": "Merci, je suis ravi d''être ici.", "next": "end_strong"}]}, "end_strong": {"speaker": "recruiter", "text": "Let''s move on to the next part of the interview.", "text_fr": "Passons à la suite de l''entretien.", "end": true, "ending_label": "Présentation claire et convaincante ✅"}}}'::jsonb, is_playable = true
where title = 'Se présenter en 2 minutes'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"recruiter": "le recruteur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "recruiter", "text": "So, why are you interested in this particular position?", "text_fr": "Alors, pourquoi ce poste vous intéresse-t-il en particulier ?", "choices": [{"text": "I''ve followed your company''s work for a while and really admire your approach.", "text_fr": "Je suis le travail de votre entreprise depuis un moment et j''admire vraiment votre approche.", "next": "n2"}, {"text": "Honestly, this role matches exactly the skills I want to develop next.", "text_fr": "Honnêtement, ce poste correspond exactement aux compétences que je veux développer ensuite.", "next": "n2b"}]}, "n2": {"speaker": "recruiter", "text": "That''s good to hear. What specifically stood out to you about us?", "text_fr": "C''est bon à entendre. Qu''est-ce qui vous a marqué en particulier chez nous ?", "choices": [{"text": "Your recent sustainability initiative really impressed me.", "text_fr": "Votre récente initiative de durabilité m''a vraiment impressionné.", "next": "n3"}, {"text": "The way your team collaborates across departments seems really unique.", "text_fr": "La façon dont votre équipe collabore entre départements semble vraiment unique.", "next": "n3"}]}, "n2b": {"speaker": "recruiter", "text": "I see. Which skills specifically are you hoping to grow here?", "text_fr": "Je vois. Quelles compétences en particulier espérez-vous développer ici ?", "choices": [{"text": "Leadership — I''d love to manage a small team eventually.", "text_fr": "Le leadership — j''aimerais gérer une petite équipe éventuellement.", "next": "n3"}, {"text": "Strategic planning, since I''ve mostly done execution so far.", "text_fr": "La planification stratégique, car j''ai surtout fait de l''exécution jusqu''ici.", "next": "n3"}]}, "n3": {"speaker": "recruiter", "text": "That''s a genuine answer, I appreciate that. How do you see yourself contributing here?", "text_fr": "C''est une réponse sincère, j''apprécie. Comment vous voyez-vous contribuer ici ?", "choices": [{"text": "I''d bring fresh ideas while learning from the experienced team.", "text_fr": "J''apporterais des idées fraîches tout en apprenant de l''équipe expérimentée.", "next": "n4"}, {"text": "I think my background gives me a unique perspective for this role.", "text_fr": "Je pense que mon parcours me donne une perspective unique pour ce poste.", "next": "n4"}]}, "n4": {"speaker": "recruiter", "text": "Good answer. Do you have any questions about the role itself?", "text_fr": "Bonne réponse. Vous avez des questions sur le poste lui-même ?", "choices": [{"text": "Yes — what does success look like in this role after six months?", "text_fr": "Oui — à quoi ressemble la réussite dans ce poste après six mois ?", "next": "n5"}, {"text": "What''s the team structure like for this position?", "text_fr": "C''est quoi la structure d''équipe pour ce poste ?", "next": "n5"}]}, "n5": {"speaker": "recruiter", "text": "Good question, let me explain that in detail.", "text_fr": "Bonne question, laissez-moi expliquer ça en détail.", "choices": [{"text": "Thank you, that''s really helpful to know.", "text_fr": "Merci, c''est vraiment utile à savoir.", "next": "end_genuine"}]}, "end_genuine": {"speaker": "recruiter", "text": "You clearly did your homework on this role. I appreciate that.", "text_fr": "Vous avez clairement fait vos devoirs sur ce poste. J''apprécie ça.", "end": true, "ending_label": "Motivation sincère et bien préparée ✅"}}}'::jsonb, is_playable = true
where title = 'Répondre à "pourquoi ce poste ?"'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
